<body>
<header>SITE HEADER</header>
{{{body}}}
<footer>SITE FOOTER</footer>
</body></html>`);

    writeTemplate(templatesDir, 'default.hbs', `<article><h1>{{title}}</h1>{{{content}}}</article>`);

    writeMarkdown(contentDir, 'layered', 'Layered content', 'title: Layered');

